custom_header:
using Cxx = import "/include/c++.capnp";
$Cxx.namespace("cereal");
using Car = import "/car.capnp";

@0xb526ba661d550a59;

# custom.capnp: a home for empty structs reserved for custom forks
# These structs are guaranteed to remain reserved and empty in mainline
# cereal, so use these if you want custom events in your fork.

# DO rename the structs
# DON'T change the identifier (e.g. @0x81c2f05a394cf4af)








































# Automatic FLM adds children only to existing reserved fork carriers.
# All evidence clocks are explicitly MONOTONIC; default/version0 is invalid.


















# Live tracking trials are a separate protocol, never ReplayValidation.

0.body:
hudControl @0 :HUDControl;
steeringLimitInfo @1 :SteeringLimitInfo;

struct HUDControl {
  audibleAlert @0 :AudibleAlert;

  enum AudibleAlert {
    none @0;

    engage @1;
    disengage @2;
    refuse @3;

    warningSoft @4;
    warningImmediate @5;

    prompt @6;
    promptRepeat @7;
    promptDistracted @8;

    # Random Events
    angry @9;
    continued @10;
    dejaVu @11;
    doc @12;
    fart @13;
    firefox @14;
    goat @15;
    hal9000 @16;
    mail @17;
    nessie @18;
    noice @19;
    startup @20;
    thisIsFine @21;
    uwu @22;
  }
}

